def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    opp_defections = sum(1 for m, o in history if o == 'D')
    opp_coops = n - opp_defections
    if n < 3:
        return 'C'
    if n >= 100:
        return 'D' if opp_defections > opp_coops else 'C'
    if n >= 90:
        return 'D' if opp_defections >= 3 else 'C'
    if n >= 80:
        return 'D' if opp_defections >= 5 else 'C'
    recent = list(history[-6:])
    recent_def = sum(1 for m, o in recent if o == 'D')
    if recent_def == 0:
        return 'C'
    if recent_def >= 4:
        return 'D'
    if recent_def == 1:
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        return 'C'
    if recent_def == 2:
        return 'D' if opp_last == 'D' else 'C'
    if recent_def == 3:
        if opp_last == 'D' and my_last == 'D':
            return 'D'
        return 'C'
    return 'C'
